<?php\n\nclass Veiculo {\n    private \$quilometragem = 0;\n    \n    public function rodar(\$km) {\n        \$this->quilometragem += \$km;\n    }\n    \n    public function exibirQuilometragem() {\n        return \"Este veículo rodou \" . \$this->quilometragem . \" km\";\n    }\n}\n\necho \"Teste do Veículo:\\n\\n\";\n\n// Criar objeto\n\$carro = new Veiculo();\n\necho \"Inicial: \" . \$carro->exibirQuilometragem() . \"\\n\";\n\n// Rodar\n\$carro->rodar(150);\necho \"Depois de rodar 150: \" . \$carro->exibirQuilometragem() . \"\\n\";\n\n\$carro->rodar(250);\necho \"Depois de rodar 250: \" . \$carro->exibirQuilometragem() . \"\\n\";\n\necho \"\\n\";\n\n// Outro veículo\n\$moto = new Veiculo();\n\$moto->rodar(500);\necho \"Moto: \" . \$moto->exibirQuilometragem() . \"\\n\";\necho \"Carro: \" . \$carro->exibirQuilometragem() . \"\\n\";\n\necho \"\\n// cada instância tem sua própria quilometragem\\n\";\n\n?>"
